type AnyObj=Record<string,any>;
const root=document.getElementById('app')!;
const page=root.dataset.page||'customer';
const state:{token:string|null,user:AnyObj|null,cats:AnyObj[],orders:AnyObj[],services:AnyObj[]}={token:null,user:null,cats:[],orders:[],services:[]};
const SESSION_KEY='khadamat_session_v7';
let customerPollTimer:number|undefined;
let providerPollTimer:number|undefined;
let notificationPollTimer:number|undefined;
let lastProviderOfferIds=new Set<string>();
const acceptingOffers=new Set<string>();
let eventSource:EventSource|undefined;
let liveRefreshTimer:number|undefined;
const stopPollers=()=>{if(customerPollTimer!==undefined){clearInterval(customerPollTimer);customerPollTimer=undefined}if(providerPollTimer!==undefined){clearInterval(providerPollTimer);providerPollTimer=undefined}if(notificationPollTimer!==undefined){clearInterval(notificationPollTimer);notificationPollTimer=undefined}if(liveRefreshTimer!==undefined){clearTimeout(liveRefreshTimer);liveRefreshTimer=undefined}if(eventSource){eventSource.close();eventSource=undefined}if(offerCountdownTimer!==undefined){clearInterval(offerCountdownTimer);offerCountdownTimer=undefined}};
let pendingAssistImage:File|null=null;
let realtime: EventSource|undefined; let providerLocationWatch:number|undefined; let providerLocationLastSent=0; let realtimeRetry:number|undefined; let offerCountdownTimer:number|undefined; let notificationModalTimer:number|undefined; let notificationModalRefreshing=false;
const stopRealtime=()=>{if(realtime){realtime.close();realtime=undefined}if(realtimeRetry!==undefined){clearTimeout(realtimeRetry);realtimeRetry=undefined}};
function toast(title:string,body:string){let box=document.getElementById('liveToasts');if(!box){box=document.createElement('div');box.id='liveToasts';box.style.cssText='position:fixed;top:16px;left:16px;z-index:99999;display:flex;flex-direction:column;gap:8px;max-width:min(380px,calc(100vw - 32px));';document.body.appendChild(box)}const el=document.createElement('div');el.style.cssText='background:#fff;border:1px solid #d9e1ea;border-radius:14px;padding:12px 14px;box-shadow:0 8px 28px rgba(0,0,0,.14);font-family:Arial,sans-serif;cursor:pointer';el.innerHTML=`<b>${esc(title)}</b><div style="margin-top:4px;color:#667085;font-size:13px">${esc(body)}</div>`;el.onclick=()=>el.remove();box.appendChild(el);setTimeout(()=>el.remove(),7000)}
async function startRealtime(){stopRealtime();if(!state.user||!state.token)return;try{const j=await api('/events/ticket',{method:'POST',body:'{}'});const es=new EventSource('/api/v1/events?ticket='+encodeURIComponent(j.ticket));realtime=es;es.addEventListener('notification',async(ev)=>{try{const n=JSON.parse((ev as MessageEvent).data||'{}');toast(n.title||'إشعار جديد',n.body||'');if(document.getElementById('notificationList')) await refreshOpenNotifications();
            if(n.type==='CHAT_MESSAGE' && n.orderId && document.getElementById('chatMessages')) { window.dispatchEvent(new CustomEvent('khadamat:chat',{detail:{orderId:n.orderId}})); }if(page==='provider'){if(['NEW_OFFER','PROVIDER_VERIFIED','PROVIDER_REJECTED','PROVIDER_SUSPENDED','PROVIDER_REACTIVATED','NEW_RATING','COMPLAINT_OPENED','COMPLAINT_REPLIED','COMPLAINT_CLOSED','CHAT_MESSAGE'].includes(n.type)) await provider();}else if(page==='customer'){if(['ORDER_RECEIVED','ORDER_ACCEPTED','PROVIDER_ON_THE_WAY','SERVICE_STARTED','ORDER_COMPLETED','ORDER_CANCELLED','NO_PROVIDER_FOUND','NEW_QUOTE','QUOTE_ACCEPTED','COMPLAINT_OPENED','COMPLAINT_REPLIED','COMPLAINT_CLOSED','CHAT_MESSAGE'].includes(n.type)) await customer();}}catch{}});
        es.addEventListener('chat_message',(ev)=>{try{const d=JSON.parse((ev as MessageEvent).data||'{}');if(d?.orderId)window.dispatchEvent(new CustomEvent('khadamat:chat-message',{detail:d}));}catch{}});es.addEventListener('trip_location',(ev)=>{try{const d=JSON.parse((ev as MessageEvent).data||'{}');if(d?.orderId)window.dispatchEvent(new CustomEvent('khadamat:trip-location',{detail:d}));}catch{}});es.addEventListener('sync',async(ev)=>{try{const data=JSON.parse((ev as MessageEvent).data||'{}');if(data?.scope==='catalog' || data?.scope==='settings' || data?.scope==='users' || data?.scope==='provider' || data?.scope==='addresses' || data?.scope==='orders' || data?.scope==='admin'){if(page==='provider') await provider(); else if(page==='customer') await customer(); else if(page==='admin') await admin();}}catch{}});es.onerror=()=>{es.close();realtime=undefined;if(state.user&&state.token){realtimeRetry=window.setTimeout(()=>{startRealtime().catch(()=>{})},4000)}};}catch{realtimeRetry=window.setTimeout(()=>{startRealtime().catch(()=>{})},5000)}}
const esc=(v:any)=>String(v??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const newIdempotencyKey=()=>{try{return crypto.randomUUID()}catch{return 'order-'+Date.now()+'-'+Math.random().toString(36).slice(2)}};
const uniqueOrders=(items:any[])=>{const seen=new Set<string>();return items.filter(x=>{const id=String(x?.id||'');if(!id||seen.has(id))return false;seen.add(id);return true})};
const uniqueBy=(items:any[],key:(x:any)=>string)=>{const seen=new Set<string>();return items.filter(x=>{const k=key(x);if(!k||seen.has(k))return false;seen.add(k);return true})};
const OFFLINE_QUEUE='khadamat_order_queue_v1';
function queueOrder(body:any,key:string){const q=JSON.parse(localStorage.getItem(OFFLINE_QUEUE)||'[]');q.push({body,key,createdAt:Date.now()});localStorage.setItem(OFFLINE_QUEUE,JSON.stringify(q.slice(-20)));}
async function flushOrderQueue(){if(!navigator.onLine||!state.token)return;const q=JSON.parse(localStorage.getItem(OFFLINE_QUEUE)||'[]');if(!q.length)return;const left:any[]=[];for(const item of q){try{await api('/orders',{method:'POST',headers:{'Idempotency-Key':item.key},body:JSON.stringify(item.body)})}catch{left.push(item)}}localStorage.setItem(OFFLINE_QUEUE,JSON.stringify(left));if(q.length!==left.length)toast('تمت المزامنة','تم إرسال الطلبات المحفوظة بعد عودة الإنترنت.')}
window.addEventListener('online',()=>{flushOrderQueue().catch(()=>{})});
async function api(path:string,opts:RequestInit={},retry=true){const h=new Headers(opts.headers||{});h.set('Content-Type','application/json');if(state.token)h.set('Authorization',`Bearer ${state.token}`);const r=await fetch('/api/v1'+path,{...opts,headers:h});const j=await r.json().catch(()=>({}));if(r.status===401&&retry&&path!=='/auth/refresh'&&sessionStorage.getItem(SESSION_KEY)){try{const refreshed=await fetch('/api/v1/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'khadamat'},body:'{}'});const rj=await refreshed.json().catch(()=>({}));if(refreshed.ok&&rj.accessToken){saveSession(rj);return api(path,opts,false)}}catch{}sessionStorage.removeItem(SESSION_KEY);state.token=null;state.user=null;throw new Error('انتهت الجلسة، يرجى تسجيل الدخول من جديد')}if(!r.ok)throw new Error(j?.error?.message||'حدث خطأ');return j;}
function saveSession(j:AnyObj){state.token=j.accessToken;state.user=j.user;sessionStorage.setItem(SESSION_KEY,JSON.stringify({accessToken:j.accessToken,user:j.user}));}
async function openPrivateFile(path:string){
  const win=window.open('about:blank','_blank');
  if(!win){alert('اسمح بفتح النوافذ المنبثقة لعرض الملف.');return}
  win.document.write('<p style="font-family:Arial;padding:24px">جارٍ فتح الملف...</p>');
  try{
    let r=await fetch(path,{headers:state.token?{Authorization:`Bearer ${state.token}`}:{}});
    if(r.status===401){
      try{
        const refreshed=await fetch('/api/v1/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'khadamat'},body:'{}'});
        const j=await refreshed.json().catch(()=>({}));
        if(refreshed.ok&&j.accessToken){saveSession(j);r=await fetch(path,{headers:{Authorization:`Bearer ${state.token}`}})}
      }catch{}
    }
    if(!r.ok)throw new Error(r.status===401?'انتهت الجلسة، يرجى تسجيل الدخول من جديد':'تعذر فتح الملف');
    const blob=await r.blob();
    const url=URL.createObjectURL(blob);
    win.location.href=url;
    window.setTimeout(()=>URL.revokeObjectURL(url),60000);
  }catch(e){
    win.document.body.innerHTML=`<div style="font-family:Arial;padding:24px"><h3>تعذر فتح الملف</h3><p>${esc((e as Error).message)}</p></div>`;
  }
}
function restoreSession(){try{const raw=sessionStorage.getItem(SESSION_KEY);if(!raw)return false;const j=JSON.parse(raw);if(!j?.accessToken||!j?.user){sessionStorage.removeItem(SESSION_KEY);return false}state.token=j.accessToken;state.user=j.user;return true}catch{sessionStorage.removeItem(SESSION_KEY);return false}}
async function logout(){stopRealtime();try{if(state.token)await api('/auth/logout',{method:'POST',body:'{}'});}catch{}state.token=null;state.user=null;sessionStorage.removeItem(SESSION_KEY);location.replace('/')}
const STATUS_AR:any={PENDING:'قيد المراجعة',SEARCHING:'جارٍ البحث عن مقدم خدمة',ASSIGNED:'تم ترشيح مقدم خدمة',ACCEPTED:'تم قبول الطلب',ON_THE_WAY:'مقدم الخدمة في الطريق',IN_PROGRESS:'الخدمة قيد التنفيذ',COMPLETED:'مكتمل',CANCELLED:'ملغي',DISPUTED:'متنازع عليه'};
const statusAr=(s:any)=>STATUS_AR[String(s)]||String(s||'غير محدد');
const VERIFY_AR:any={PENDING:'قيد التحقق',VERIFIED:'موثق',REJECTED:'مرفوض',SUSPENDED:'موقوف'};
const verifyAr=(s:any)=>VERIFY_AR[String(s)]||String(s||'غير محدد');
const docTypeAr=(v:string)=>({ID:'الهوية',LICENSE:'الترخيص',COMMERCIAL_REG:'السجل التجاري',CERTIFICATE:'الشهادة',PHOTO_WORK:'صور الأعمال'} as any)[v]||v;
const docStatusAr=(v:string)=>({PENDING:'قيد المراجعة',APPROVED:'مقبول',REJECTED:'مرفوض'} as any)[v]||v;
const formatDateTime=(v:any)=>{if(!v)return '—';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);return new Intl.DateTimeFormat('ar-YE',{year:'numeric',month:'long',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true}).format(d)};
async function refreshNotificationBadge(){try{const j=await api('/notifications?limit=1');const el=document.getElementById('notificationCount');if(el)el.textContent=j.unreadCount?`(${j.unreadCount})`:'';const btn=document.getElementById('notificationsBtn');if(btn){btn.classList.toggle('attention',Number(j.unreadCount||0)>0);btn.title=j.unreadCount?`لديك ${j.unreadCount} إشعار غير مقروء`:'الإشعارات';}}catch{}}
function startNotificationPolling(){if(notificationPollTimer!==undefined)clearInterval(notificationPollTimer);if(!state.user||!state.token)return;refreshNotificationBadge().catch(()=>{});notificationPollTimer=window.setInterval(()=>{refreshNotificationBadge().catch(()=>{});if(page==='provider')refreshProviderNotificationSurface().catch(()=>{});},5000)}
async function refreshProviderNotificationSurface(){if(page!=='provider'||!state.user||!state.token)return;try{const j=await api('/notifications?limit=5');const unread=(j.notifications||[]).filter((n:any)=>!n.read);const latest=unread[0];if(latest?.type==='NEW_OFFER'){const id=String(latest.id||'');if(id && !sessionStorage.getItem('khadamat_seen_notif_'+id)){sessionStorage.setItem('khadamat_seen_notif_'+id,'1');toast(latest.title||'طلب جديد',latest.body||'');}}}catch{}}
function notificationAction(n:AnyObj){
  const d=n.data||{};
  if(n.type==='NEW_QUOTE'&&d.orderId&&d.quoteId){
    if(d.quoteStatus && d.quoteStatus!=='SUBMITTED') return `<div class="notification-action notification-action-done"><b>تم التعامل مع عرض السعر</b><span class="status">${esc(d.quoteStatusAr||d.quoteStatus)}</span><div class="notification-actions"><button class="btn secondary notification-view-quotes" data-order-id="${esc(d.orderId)}" type="button">عرض التفاصيل</button></div></div>`;
    return `<div class="notification-action"><b>إجراء مطلوب منك</b><span>راجع عرض السعر ثم اختر قبول العرض أو رفضه.</span><div class="notification-actions"><button class="btn notification-accept-quote" data-order-id="${esc(d.orderId)}" data-quote-id="${esc(d.quoteId)}" type="button">قبول العرض</button><button class="btn danger notification-reject-quote" data-order-id="${esc(d.orderId)}" data-quote-id="${esc(d.quoteId)}" type="button">رفض العرض</button><button class="btn secondary notification-view-quotes" data-order-id="${esc(d.orderId)}" type="button">عرض التفاصيل</button></div></div>`;
  }
  if(['PROVIDER_VERIFIED','PROVIDER_REJECTED'].includes(n.type)&&page==='provider')return `<div class="notification-action"><button class="btn secondary notification-provider-action" type="button">فتح لوحة مقدم الخدمة</button></div>`;
  if(n.type==='ORDER_COMPLETED'&&page==='customer'&&d.orderId)return `<div class="notification-action"><button class="btn notification-order-action" data-order-id="${esc(d.orderId)}" type="button">⭐ فتح التقييم</button><button class="btn secondary notification-view-order" data-order-id="${esc(d.orderId)}" type="button">عرض الطلب</button></div>`;
  return '';
}
async function fetchNotifications(){const j=await api('/notifications?limit=30');return j.notifications||[]}
async function enrichQuoteNotifications(ns:any[]){
  if(page!=='customer')return ns;
  const quoteNs=ns.filter((n:any)=>n.type==='NEW_QUOTE'&&n.data?.orderId&&n.data?.quoteId);
  await Promise.all(quoteNs.map(async(n:any)=>{try{const j=await api('/orders/'+encodeURIComponent(n.data.orderId)+'/quotes');const q=(j.quotes||[]).find((x:any)=>x.id===n.data.quoteId);if(q){n.data.quoteStatus=q.status;n.data.quoteStatusAr=({SUBMITTED:'بانتظار قرارك',ACCEPTED:'تم قبول العرض',REJECTED:'تم رفض العرض',EXPIRED:'انتهت صلاحية العرض',WITHDRAWN:'سحب مقدم الخدمة العرض'} as any)[q.status]||q.status;}}catch{}}));
  return ns;
}
async function renderNotificationList(ns:any[]){const el=document.getElementById('notificationList');if(!el)return;await enrichQuoteNotifications(ns);el.innerHTML=ns.length?ns.map((n:any)=>`<div class="notification-card ${n.read?'is-read':''}" data-notification="${esc(n.id)}"><div class="notification-card-head"><span class="notification-dot ${n.read?'':'unread'}"></span><b>${esc(n.title)}</b><small class="muted">${esc(formatDateTime(n.createdAt))}</small></div><p class="muted">${esc(n.body)}</p>${notificationAction(n)}</div>`).join(''):'<div class="card empty">لا توجد إشعارات.</div>';bindNotificationActions()}
async function refreshOpenNotifications(){if(!document.getElementById('notificationList')||notificationModalRefreshing)return;notificationModalRefreshing=true;try{await renderNotificationList(await fetchNotifications());await refreshNotificationBadge()}catch{}finally{notificationModalRefreshing=false}}
function bindNotificationActions(){
 document.querySelectorAll('[data-notification]').forEach(x=>x.addEventListener('click',async(e)=>{if((e.target as HTMLElement).closest('button'))return;try{await api('/notifications/'+encodeURIComponent((x as HTMLElement).dataset.notification||'')+'/read',{method:'POST',body:'{}'});x.classList.add('is-read');x.querySelector('.notification-dot')?.classList.remove('unread');await refreshNotificationBadge()}catch{}}));
 document.querySelectorAll('.notification-accept-quote').forEach(x=>x.addEventListener('click',async()=>{const b=x as HTMLButtonElement;b.disabled=true;try{await api('/orders/'+encodeURIComponent(b.dataset.orderId||'')+'/quotes/'+encodeURIComponent(b.dataset.quoteId||'')+'/accept',{method:'POST',body:'{}'});const row=b.closest('[data-notification]');if(row)row.innerHTML='<div class="notification-success-state"><span>✓</span><div><b>تم قبول عرض السعر</b><small>تم تحديث الطلب وسيظهر أي تقدم جديد تلقائيًا.</small></div></div>';await api('/notifications/'+encodeURIComponent(b.closest('[data-notification]')?.getAttribute('data-notification')||'')+'/read',{method:'POST',body:'{}'});await refreshNotificationBadge();await customer()}catch(e){b.disabled=false;alert((e as Error).message)}}));
 document.querySelectorAll('.notification-reject-quote').forEach(x=>x.addEventListener('click',async()=>{const b=x as HTMLButtonElement;b.disabled=true;try{await api('/orders/'+encodeURIComponent(b.dataset.orderId||'')+'/quotes/'+encodeURIComponent(b.dataset.quoteId||'')+'/reject',{method:'POST',body:'{}'});await api('/notifications/'+encodeURIComponent(b.closest('[data-notification]')?.getAttribute('data-notification')||'')+'/read',{method:'POST',body:'{}'});await refreshOpenNotifications()}catch(e){b.disabled=false;alert((e as Error).message)}}));
 document.querySelectorAll('.notification-view-quotes').forEach(x=>x.addEventListener('click',async()=>{const b=x as HTMLElement;closeModal();await openOrderQuotes(b.dataset.orderId||'')}));
 document.querySelectorAll('.notification-order-action').forEach(x=>x.addEventListener('click',async()=>{const b=x as HTMLElement;const orderId=b.dataset.orderId||'';if(!orderId)return;closeModal();try{await openRating(orderId)}catch(e){alert((e as Error).message)}}));
 document.querySelectorAll('.notification-view-order').forEach(x=>x.addEventListener('click',async()=>{const b=x as HTMLElement;const orderId=b.dataset.orderId||'';if(!orderId)return;closeModal();try{await openOrder(orderId)}catch(e){alert((e as Error).message)}}));
 document.querySelectorAll('.notification-provider-action').forEach(x=>x.addEventListener('click',()=>{closeModal();provider()}));
}
async function openNotifications(){try{const ns=await fetchNotifications();showModal(`<div class="service-picker-head notification-modal-head"><div><h2>الإشعارات</h2><p class="muted">تتحدث هذه النافذة تلقائيًا عند وصول أي تحديث جديد.</p></div><button class="btn secondary" id="readAllNotifications" type="button">✓ تحديد الكل كمقروء</button></div><div id="notificationLiveState" class="notification-live-state"><span class="live-pulse"></span> التحديث المباشر مفعل</div><div id="notificationList"></div>`);await renderNotificationList(ns);document.getElementById('readAllNotifications')?.addEventListener('click',async()=>{await api('/notifications/read-all',{method:'POST',body:'{}'});await refreshOpenNotifications()});if(notificationModalTimer)clearInterval(notificationModalTimer);notificationModalTimer=window.setInterval(()=>refreshOpenNotifications(),3000);await refreshNotificationBadge()}catch(e){alert((e as Error).message)}}
