function shell(content:string,title='خدمات'){const portal=page==='provider'?`<a class="portal-link portal-customer" href="/" aria-label="الانتقال إلى واجهة العميل">↩ واجهة العميل</a>`:page==='admin'?`<a class="portal-link portal-customer" href="/" aria-label="الانتقال إلى واجهة العميل">↩ واجهة العميل</a>`:`<a class="portal-link portal-provider" href="/provider.html" data-provider-link aria-label="الانتقال إلى واجهة مقدم الخدمة">↗ واجهة مقدم الخدمة</a>`;const adminLink=state.user?.role==='ADMIN'&&page!=='admin'?`<a class="portal-link portal-admin" href="/admin" aria-label="الانتقال إلى لوحة الإدارة">⚙ لوحة الإدارة</a>`:'';root.innerHTML=`<main class="shell"><div class="top app-topbar"><a class="brand brand-lockup" href="/" aria-label="خدمات"><span class="brand-mark">خ</span><span><strong>خدمات</strong><small>كل خدمة تحتاجها في مكان واحد</small></span></a><div class="row top-actions">${portal}${adminLink}<button class="btn secondary small about-btn" id="aboutBtn" type="button">حول التطبيق</button>${state.user?`<button class="btn secondary small account-btn" id="accountBtn" type="button">حسابي</button><button class="btn secondary small notification-top-btn" id="notificationsBtn" type="button">🔔 <span id="notificationCount"></span></button><button class="btn secondary small logout-btn" id="logout">خروج</button>`:''}</div></div>${content}</main>`;document.getElementById('aboutBtn')?.addEventListener('click',openAbout);document.getElementById('logout')?.addEventListener('click',logout);document.getElementById('notificationsBtn')?.addEventListener('click',openNotifications);document.getElementById('accountBtn')?.addEventListener('click',openAccount);if(state.user)refreshNotificationBadge().catch(()=>{});document.querySelectorAll('[data-provider-link]').forEach(x=>x.addEventListener('click',e=>{e.preventDefault();window.location.assign('/provider.html')}))}
async function openAccount(){
  try{
    const j=await api('/auth/me'); const u=j.user||state.user||{};
    const isProvider=u.role==='PROVIDER';
    showModal(`<h2>حسابي</h2><form id="accountForm"><div class="grid"><div class="field"><label>الاسم</label><input name="fullName" value="${esc(u.fullName||'')}" disabled></div><div class="field"><label>الهاتف</label><input name="phone" value="${esc(u.phone||'')}" disabled></div><div class="field"><label>البريد الإلكتروني</label><input name="email" value="${esc(u.email||'')}" disabled></div></div>${isProvider?`<div class="field"><label>اسم النشاط</label><input name="displayName" value="${esc(u.provider?.displayName||'')}" maxlength="80"></div><div class="field"><label>نبذة</label><textarea name="bio" maxlength="1000">${esc(u.provider?.bio||'')}</textarea></div>`:''}<button class="btn">حفظ التغييرات</button><p id="accountMsg" class="muted"></p></form>`);
    document.getElementById('accountForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);const msg=document.getElementById('accountMsg')!;try{if(isProvider){await api('/provider/profile',{method:'PATCH',body:JSON.stringify({displayName:String(f.get('displayName')||''),bio:String(f.get('bio')||'')})})}else{await api('/me/profile',{method:'PATCH',body:JSON.stringify({fullName:String(f.get('fullName')||'')})})}msg.textContent='تم حفظ التغييرات بنجاح';msg.className='success';}catch(x){msg.textContent=(x as Error).message;msg.className='error'}});
  }catch(e){alert((e as Error).message)}
}

function authBox(next=page){const isProvider=next==='provider';const isAdmin=next==='admin';shell(`<div class="hero"><h1>${isAdmin?'دخول لوحة الإدارة':isProvider?'منصة مقدم الخدمة':'كل خدمة تحتاجها... في مكان واحد.'}</h1><p class="muted">${isAdmin?'هذه الصفحة مخصصة لحسابات الإدارة المعتمدة فقط.':'لا تبحث عن مقدم الخدمة، اطلب الخدمة فقط.'}</p></div><div class="card"><div class="nav">${isAdmin?'':'<button class="btn" id="tabLogin">دخول</button><button class="btn secondary" id="tabReg">حساب جديد</button>'}</div><div id="authForm"></div><div class="auth-switch">${isAdmin?'<span class="muted">لا يوجد إنشاء حساب مدير من هذه الصفحة.</span>':`<span class="muted">${isProvider?'تريد طلب خدمة بدل تقديمها؟':'هل تريد تقديم خدمة للعملاء؟'}</span> <a class="choose-link" href="${isProvider?'/':'/provider.html'}">${isProvider?'العودة لواجهة العميل':'الدخول إلى منصة مقدم الخدمة'}</a>`}</div></div>`);let mode='login';const draw=()=>{const providerReg=next==='provider';document.getElementById('authForm')!.innerHTML=mode==='login'?`<form id="form" autocomplete="on" novalidate><div class="field"><label>الهاتف أو البريد الإلكتروني</label><input name="identifier" type="text" autocomplete="username" autocapitalize="none" spellcheck="false" inputmode="email" value="${isAdmin?'admin@khadamat.local':''}" required></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn">دخول</button><p id="msg"></p></form>`:`<form id="form" autocomplete="on" novalidate><div class="field"><label>الاسم</label><input name="fullName" type="text" autocomplete="name" required></div><div class="field"><label>الهاتف</label><input name="phone" type="tel" autocomplete="tel" inputmode="tel" required placeholder="+967..."></div><div class="field"><label>البريد الإلكتروني${providerReg?" (إلزامي)":" (اختياري)"}</label><input name="email" type="email" autocomplete="email" autocapitalize="none" spellcheck="false" inputmode="email" ${providerReg?"required":""}></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" autocomplete="new-password" required></div>${providerReg?`<div class="field"><label>نوع مقدم الخدمة</label><select name="providerType"><option value="INDIVIDUAL">فرد</option><option value="TECHNICIAN">فني</option><option value="WORKER">عامل</option><option value="DRIVER">سائق</option><option value="COMPANY">شركة</option></select></div><div class="field"><label>اسم النشاط أو الاسم الظاهر</label><input name="displayName" required></div><div class="field"><label>نبذة مختصرة</label><textarea name="bio" placeholder="ما الخدمات التي تقدمها؟"></textarea></div>`:''}<button class="btn">${providerReg?'إنشاء حساب مقدم خدمة':'إنشاء حساب عميل'}</button><p id="msg"></p></form>`;const form=document.getElementById('form') as HTMLFormElement;form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form);const b:any={};f.forEach((v,k)=>b[k]=v);try{const payload:any={...b,role:providerReg?'PROVIDER':'CUSTOMER',locale:'ar'};if(providerReg){payload.provider={providerType:b.providerType,displayName:b.displayName,bio:b.bio};if(b.providerType==='COMPANY'){payload.provider.companyName=b.displayName}delete payload.providerType;delete payload.displayName;delete payload.bio}const j=mode==='login'?await api('/auth/login',{method:'POST',body:JSON.stringify(b)}):await api('/auth/register',{method:'POST',body:JSON.stringify(payload)});saveSession(j);startRealtime().catch(()=>{});startNotificationPolling();location.href=next==='provider'?'/provider.html':next==='admin'?'/admin':'/';}catch(x){document.getElementById('msg')!.textContent=(x as Error).message;document.getElementById('msg')!.className='error'}})};document.getElementById('tabLogin')?.addEventListener('click',()=>{mode='login';draw()});document.getElementById('tabReg')?.addEventListener('click',()=>{mode='reg';draw()});draw()}
async function customer(){if(!state.user){authBox();return}if(state.user!.role!=='CUSTOMER'){shell(`<div class="notice">هذا الحساب ليس حساب عميل. <button class="btn" id="go">فتح الواجهة المناسبة</button></div>`);document.getElementById('go')!.onclick=()=>location.href=state.user!.role==='PROVIDER'?'/provider.html':'/admin';return}try{const [c,o]=await Promise.all([api('/categories'),api('/orders')]);state.cats=c.categories||[];state.orders=uniqueOrders((o.orders||[]).filter((x:any)=>x.status!=='CANCELLED'));state.services=[];for(const cat of state.cats){try{const j=await api('/categories/'+encodeURIComponent(cat.slug)+'/services');state.services.push(...(j.services||[]).map((svc:any)=>({...svc,categorySlug:cat.slug,categoryName:cat.name,categoryIcon:cat.icon})))}catch{}}renderCustomer();
    stopPollers();
    customerPollTimer=window.setInterval(async()=>{try{const o=await api('/orders');state.orders=uniqueOrders((o.orders||[]).filter((x:any)=>x.status!=='CANCELLED'));const box=document.getElementById('orders');if(box)box.innerHTML=state.orders.length?state.orders.map(orderCard).join(''):'<div class="card empty">لا توجد طلبات حتى الآن<br><span class="muted">ابدأ باختيار خدمة من القائمة أعلاه</span></div>';const count=document.querySelector('#ordersTab .count');if(count)count.textContent=String(state.orders.length);document.querySelectorAll('[data-order]').forEach(x=>{x.addEventListener('click',e=>{if((e.target as HTMLElement).closest('[data-rate-order]'))return;openOrder((x as HTMLElement).dataset.order!)});x.addEventListener('keydown',e=>{if((e as KeyboardEvent).key==='Enter'||(e as KeyboardEvent).key===' '){e.preventDefault();openOrder((x as HTMLElement).dataset.order!)}})});document.querySelectorAll('[data-rate-order]').forEach(x=>x.addEventListener('click',e=>{e.stopPropagation();openRating((x as HTMLElement).dataset.rateOrder!)}));document.querySelectorAll('[data-reorder-order]').forEach(x=>x.addEventListener('click',async e=>{e.stopPropagation();try{const j=await api('/orders/'+(x as HTMLElement).dataset.reorderOrder+'/reorder',{method:'POST',body:'{}'});openOrderForm(j.draft.serviceId,j.draft)}catch(err){alert((err as Error).message)}}));}catch{}} ,5000);
  }catch(e){shell(`<div class="card error">${esc((e as Error).message)}</div>`)} }
function pickQuickServices(services:AnyObj[],limit=7){const picked:AnyObj[]=[];const seenCats=new Set<string>();for(const s of services){const key=String(s.categoryId||s.categorySlug||'');if(!seenCats.has(key)){seenCats.add(key);picked.push(s);if(picked.length>=limit)return picked;}}for(const s of services){if(!picked.some(x=>x.id===s.id)){picked.push(s);if(picked.length>=limit)break;}}return picked;}
