async function setProviderLocation(){
  const msg=document.getElementById('providerLocationMsg');const btn=document.getElementById('setProviderLocation') as HTMLButtonElement;
  if(!navigator.geolocation){if(msg)msg.textContent='المتصفح لا يدعم تحديد الموقع';return}
  btn.disabled=true;if(msg)msg.textContent='جارٍ تحديد أفضل موقع للجهاز...';let best:GeolocationPosition|null=null;let watch:number|undefined;const started=Date.now();
  const finish=async()=>{if(watch!==undefined)navigator.geolocation.clearWatch(watch);btn.disabled=false;if(!best){if(msg)msg.textContent='تعذر الحصول على موقع الجهاز';return}try{await api('/provider/profile',{method:'PATCH',body:JSON.stringify({baseLocation:{lat:best.coords.latitude,lng:best.coords.longitude}})});if(msg)msg.textContent=`تم حفظ الموقع بدقة تقريبية ${Math.round(best.coords.accuracy)} متر.`;const t=document.getElementById('providerLocationText');if(t)t.textContent=`محفوظ: ${best.coords.latitude.toFixed(6)} ، ${best.coords.longitude.toFixed(6)}`}catch(e){if(msg)msg.textContent=(e as Error).message}};
  watch=navigator.geolocation.watchPosition(pos=>{if(!best||pos.coords.accuracy<best.coords.accuracy)best=pos;if(best.coords.accuracy<=100||Date.now()-started>45000)finish()},err=>{if(Date.now()-started>45000)finish();else if(msg)msg.textContent='فعّل GPS وخدمات الموقع ثم انتظر...'}, {enableHighAccuracy:true,maximumAge:0,timeout:20000});
  window.setTimeout(finish,60000);
}
function startOfferCountdowns(){if(offerCountdownTimer!==undefined)clearInterval(offerCountdownTimer);const tick=()=>{document.querySelectorAll('[data-expires]').forEach(el=>{const t=Date.parse((el as HTMLElement).dataset.expires||'');const left=Math.max(0,Math.ceil((t-Date.now())/1000));const m=Math.floor(left/60),s=left%60;(el as HTMLElement).textContent=left?`⏳ متبقٍ لقبول الطلب: ${m}:${String(s).padStart(2,'0')}`:'انتهت مهلة العرض';(el as HTMLElement).classList.toggle('error',left===0)})};tick();offerCountdownTimer=window.setInterval(tick,1000)}

function bindProviderLiveActions(){
  document.querySelectorAll('[data-accept]').forEach(x=>x.addEventListener('click',async()=>{const b=x as HTMLButtonElement;const offerId=String(b.dataset.accept||'');if(!offerId||acceptingOffers.has(offerId))return;acceptingOffers.add(offerId);b.disabled=true;b.textContent='جارٍ قبول الطلب...';try{await api('/provider/offers/'+encodeURIComponent(offerId)+'/accept',{method:'POST',body:'{}'});acceptingOffers.delete(offerId);await provider()}catch(e){acceptingOffers.delete(offerId);b.disabled=false;b.textContent='✓ قبول الطلب';alert((e as Error).message)}}));
  document.querySelectorAll('[data-quote-offer]').forEach(x=>x.addEventListener('click',()=>openProviderQuote((x as HTMLElement).dataset.quoteOffer!)));
  document.querySelectorAll('[data-reject]').forEach(x=>x.addEventListener('click',async()=>{const b=x as HTMLButtonElement;b.disabled=true;try{await api('/provider/offers/'+b.dataset.reject+'/reject',{method:'POST',body:'{}'});await provider()}catch(e){b.disabled=false;alert((e as Error).message)}}));
  document.querySelectorAll('[data-status]').forEach(x=>x.addEventListener('click',async()=>{try{await api('/provider/orders/'+(x as HTMLElement).dataset.id+'/status',{method:'POST',body:JSON.stringify({to:(x as HTMLElement).dataset.status})});await provider()}catch(e){alert((e as Error).message)}}));
}

function providerOrder(o:AnyObj){const map:any={ACCEPTED:'ON_THE_WAY',ON_THE_WAY:'IN_PROGRESS',IN_PROGRESS:'COMPLETED'};const next=map[o.status];const label=next==='ON_THE_WAY'?'في الطريق':next==='IN_PROGRESS'?'بدء الخدمة':'إكمال الطلب';return `<div class="card order-card"><button class="order-card-main" data-provider-order="${esc(o.id)}" type="button"><div class="row"><b>${esc(o.code)}</b><span class="status status-${esc(String(o.status).toLowerCase())}">${esc(statusAr(o.status))}</span></div><p>${esc(o.service.name)} — ${esc(o.description)}</p>${o.location?`<small class="muted">📍 موقع محفوظ مع الطلب</small>`:''}</button>${next?`<div style="margin-top:10px"><button class="btn" type="button" data-id="${esc(o.id)}" data-status="${next}">${label}</button></div>`:''}</div>`}
async function openProviderOrder(id:string){try{const j=await api('/orders/'+id);const o=j.order;const loc=o.location||{};const hasLoc=Number.isFinite(Number(loc.lat))&&Number.isFinite(Number(loc.lng));const lat=Number(loc.lat),lng=Number(loc.lng);const mapUrl=hasLoc?`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lng}#map=18/${lat}/${lng}`:'';const g=hasLoc?`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${lat},${lng}`)}&travelmode=driving`:'';showModal(`<h2>${esc(o.code)}</h2><p><b>الخدمة:</b> ${esc(o.service.name)}</p><p><b>الحالة:</b> ${esc(statusAr(o.status))}</p><p>${esc(o.description)}</p>${o.trip?`<div class="trip-summary card"><b>🛵 تفاصيل المشوار</b><p>الغرض: ${esc(o.trip.purposeName)} · المسافة: ${esc(o.trip.distanceKm)} كم · الأجرة: ${esc(o.trip.fare)} ${esc(o.trip.currency)}</p><p class="muted">الوجهة: ${esc(o.trip.destination.addressText||`${Number(o.trip.destination.lat).toFixed(6)} ، ${Number(o.trip.destination.lng).toFixed(6)}`)}</p></div>`:''}${o.customer?.phone?`<div class="card"><b>👤 العميل: ${esc(o.customer.fullName)}</b><p class="muted">📞 ${esc(o.customer.phone)}</p><a class="btn secondary small" href="tel:${esc(o.customer.phone)}">اتصال</a></div>`:''}${o.customer?`<button class="btn secondary" id="providerChatBtn" type="button">💬 محادثة مع العميل</button>`:''}${o.trip&&o.status==='IN_PROGRESS'?`<div class="row"><button class="btn secondary" id="startWaitBtn" type="button">⏱️ بدء الانتظار</button><button class="btn secondary" id="stopWaitBtn" type="button">⏹️ إنهاء الانتظار</button></div>`:''}${['ACCEPTED','ON_THE_WAY','IN_PROGRESS','COMPLETED','DISPUTED'].includes(o.status)?`<button class="btn secondary" id="providerComplaintBtn" type="button">⚠️ متابعة الشكوى</button>`:''}${o.status==='COMPLETED'?`<div class="field"><label>تقييم العميل</label><select id="customerScore"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select><textarea id="customerComment" placeholder="تعليق اختياري"></textarea><button class="btn" id="rateCustomer" type="button">إرسال تقييم العميل</button></div>`:''}${hasLoc?`<div class="card"><h3>📍 موقع العميل</h3><p class="muted">الإحداثيات المحفوظة في الطلب: ${lat.toFixed(6)} ، ${lng.toFixed(6)}</p><div id="providerOrderMap" style="height:280px;width:100%;border-radius:12px;overflow:hidden"></div><div class="row" style="margin-top:10px"><a class="btn secondary" target="_blank" rel="noopener" href="${mapUrl}">فتح الخريطة</a><a class="btn" target="_blank" rel="noopener" href="${g}">🧭 ابدأ الاتجاهات</a></div></div>`:'<div class="card error">لا يوجد موقع محفوظ لهذا الطلب</div>'}<div class="order-timeline">${renderOrderTimeline(o.status)}</div>`);if(hasLoc){const el=document.getElementById('providerOrderMap');const L=(window as any).L;if(el&&L){const map=L.map(el,{scrollWheelZoom:false}).setView([lat,lng],18);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);L.marker([lat,lng]).addTo(map).bindPopup('موقع العميل').openPopup();setTimeout(()=>map.invalidateSize(),100)}}document.getElementById('providerChatBtn')?.addEventListener('click',()=>openOrderChat(id));document.getElementById('startWaitBtn')?.addEventListener('click',async()=>{try{await api('/trips/'+encodeURIComponent(id)+'/wait',{method:'POST',body:JSON.stringify({action:'START'})});alert('بدأ احتساب وقت الانتظار')}catch(e){alert((e as Error).message)}});document.getElementById('stopWaitBtn')?.addEventListener('click',async()=>{try{const w=await api('/trips/'+encodeURIComponent(id)+'/wait',{method:'POST',body:JSON.stringify({action:'STOP'})});alert(`تم إنهاء الانتظار. الدقائق: ${w.minutes} — الأجرة الحالية: ${w.fare}`)}catch(e){alert((e as Error).message)}});document.getElementById('providerComplaintBtn')?.addEventListener('click',()=>openOrderComplaint(id,true));document.getElementById('rateCustomer')?.addEventListener('click',async()=>{const b=document.getElementById('rateCustomer') as HTMLButtonElement;b.disabled=true;try{await api('/provider/orders/'+encodeURIComponent(id)+'/rate-customer',{method:'POST',body:JSON.stringify({score:Number((document.getElementById('customerScore') as HTMLSelectElement).value),comment:(document.getElementById('customerComment') as HTMLTextAreaElement).value})});alert('تم تقييم العميل');b.textContent='تم التقييم';}catch(e){b.disabled=false;alert((e as Error).message)}})}catch(e){alert((e as Error).message)}}
async function openProviderAreas(providerData:any){
  try{const j=await api('/areas');const areas=j.areas||[];const selected=new Set((providerData.serviceAreas||[]).map((x:any)=>x.id||x.areaId));showModal(`<h2>مناطق الخدمة</h2><p class="muted">اختر المناطق التي تستطيع الوصول إليها. الإسناد يعتمد أيضًا على الإحداثيات الفعلية.</p><div class="grid">${areas.map((a:any)=>`<label class="card"><input type="checkbox" data-area-check="${esc(a.id)}" ${selected.has(a.id)?'checked':''}> ${esc(a.name)} <small class="muted">${esc(a.type)}</small></label>`).join('')}</div><button class="btn" id="saveProviderAreas">حفظ المناطق</button><p id="providerAreasMsg"></p>`);document.getElementById('saveProviderAreas')?.addEventListener('click',async()=>{const ids=Array.from(document.querySelectorAll('[data-area-check]:checked')).map(x=>(x as HTMLInputElement).dataset.areaCheck);try{await api('/provider/areas',{method:'PUT',body:JSON.stringify({areaIds:ids})});closeModal();await provider()}catch(e){alert((e as Error).message)}})}catch(e){alert((e as Error).message)}}
async function openProviderAvailability(providerData:any){
  const days=['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت']; const slots=providerData.availability||[];
  showModal(`<h2>أوقات العمل</h2><p class="muted">حدد الأيام والساعات التي تستقبل فيها الطلبات.</p><div class="availability-toolbar"><button class="btn secondary small" id="selectAllDays" type="button">✓ تحديد كل الأيام</button><button class="btn secondary small" id="clearAllDays" type="button">مسح التحديد</button></div><div id="availabilityRows">${days.map((d,i)=>{const x=slots.find((z:any)=>Number(z.weekday)===i);return `<div class="card availability-day" style="margin-top:8px"><label><input type="checkbox" data-day="${i}" ${x?'checked':''}> ${d}</label><div class="row" style="margin-top:8px"><input type="time" data-start="${i}" value="${esc(x?.start||'08:00')}"><input type="time" data-end="${i}" value="${esc(x?.end||'18:00')}"></div></div>`}).join('')}</div><button class="btn availability-save" id="saveAvailability">حفظ أوقات العمل</button><p id="availabilityMsg" class="muted"></p>`);
  document.getElementById('selectAllDays')?.addEventListener('click',()=>document.querySelectorAll('[data-day]').forEach(x=>(x as HTMLInputElement).checked=true));
  document.getElementById('clearAllDays')?.addEventListener('click',()=>document.querySelectorAll('[data-day]').forEach(x=>(x as HTMLInputElement).checked=false));
  document.getElementById('saveAvailability')?.addEventListener('click',async()=>{const out:any[]=[];days.forEach((_,i)=>{const c=document.querySelector(`[data-day="${i}"]`) as HTMLInputElement;if(c?.checked){const st=(document.querySelector(`[data-start="${i}"]`) as HTMLInputElement).value;const en=(document.querySelector(`[data-end="${i}"]`) as HTMLInputElement).value;if(st&&en)out.push({weekday:i,start:st,end:en})}});const msg=document.getElementById('availabilityMsg');try{await api('/provider/availability',{method:'PUT',body:JSON.stringify({slots:out})});if(msg){msg.textContent='تم حفظ أوقات العمل بنجاح';msg.className='success'}setTimeout(()=>{closeModal();provider()},500)}catch(e){if(msg){msg.textContent=(e as Error).message;msg.className='error'}}});
}

async function admin(){
  if(!state.user){authBox('admin');return}
  if(state.user!.role!=='ADMIN'){location.href='/';return}
  let activeTab=(new URLSearchParams(location.search).get('tab')||'overview'), orderStatus='', providerStatus='PENDING';
  const load=async()=>{
    const qs=(base:string,status:string)=>status?base+encodeURIComponent(status):base;
    const [d,u,o,c,ps,cat,areas,settings,audit,liveProviders,trips,vehicles,safety,admins]=await Promise.all([
      api('/admin/dashboard'),api('/admin/users?limit=50'),api(qs('/admin/orders?limit=50&status=',orderStatus)),api('/admin/complaints?limit=50'),api(qs('/admin/providers?status=',providerStatus)),api('/admin/catalog'),api('/admin/areas'),api('/admin/settings'),api('/admin/audit-logs?limit=100'),api('/admin/live-providers'),api('/admin/trips'),api('/admin/vehicles'),api('/safety-centers'),state.user!.adminLevel==='SUPER_ADMIN'?api('/admin/admins'):Promise.resolve({admins:[]})
    ]); return {d,u,o,c,ps,cat,areas,settings,audit,liveProviders,trips,vehicles,safety,admins};
  };
  const draw=async()=>{
    try{
      const {d,u,o,c,ps,cat,areas,settings,audit,liveProviders,trips,vehicles,safety,admins}=await load(); const stats=d.stats||{};
      const statusOptions=['','PENDING','SEARCHING','ASSIGNED','ACCEPTED','ON_THE_WAY','IN_PROGRESS','COMPLETED','CANCELLED','DISPUTED'];
      const providerStatuses=['PENDING','VERIFIED','REJECTED','SUSPENDED'];
      const cats=cat.categories||[]; const allServices=cats.flatMap((x:any)=>x.services||[]);
      shell(`<div class="hero"><div class="row" style="justify-content:space-between"><div><h1>لوحة إدارة خدمات</h1><p>إدارة التشغيل والكتالوج والمناطق والإعدادات من مكان واحد.</p></div><span class="status">${esc(state.user!.adminLevel||'ADMIN')}</span></div></div>
      <div class="nav admin-tabs"><button class="btn ${activeTab==='overview'?'':'secondary'}" data-admin-tab="overview">نظرة عامة</button><button class="btn ${activeTab==='providers'?'':'secondary'}" data-admin-tab="providers">مقدمو الخدمات</button><button class="btn ${activeTab==='verification'?'':'secondary'}" data-admin-tab="verification">طلبات التوثيق</button><button class="btn ${activeTab==='catalog'?'':'secondary'}" data-admin-tab="catalog">الخدمات والكتالوج</button><button class="btn ${activeTab==='areas'?'':'secondary'}" data-admin-tab="areas">المناطق</button><button class="btn ${activeTab==='settings'?'':'secondary'}" data-admin-tab="settings">الإعدادات</button><button class="btn ${activeTab==='account'?'':'secondary'}" data-admin-tab="account">حسابي</button><button class="btn ${activeTab==='orders'?'':'secondary'}" data-admin-tab="orders">الطلبات</button><button class="btn ${activeTab==='trips'?'':'secondary'}" data-admin-tab="trips">🛵 إدارة المشاوير</button><button class="btn ${activeTab==='live'?'':'secondary'}" data-admin-tab="live">📍 المواقع الحية</button><button class="btn ${activeTab==='vehicles'?'':'secondary'}" data-admin-tab="vehicles">🚗 المركبات</button><button class="btn ${activeTab==='safety'?'':'secondary'}" data-admin-tab="safety">🛡️ مراكز الأمان</button><button class="btn ${activeTab==='complaints'?'':'secondary'}" data-admin-tab="complaints">الشكاوى</button><button class="btn ${activeTab==='users'?'':'secondary'}" data-admin-tab="users">المستخدمون</button>${state.user!.adminLevel==='SUPER_ADMIN'?`<button class="btn ${activeTab==='admins'?'':'secondary'}" data-admin-tab="admins">المديرون والمشرفون</button>`:''}<button class="btn ${activeTab==='audit'?'':'secondary'}" data-admin-tab="audit">سجل العمليات</button></div>
      ${activeTab==='overview'?`<div class="card" style="border:2px solid #2563eb"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">🔐 طلبات التوثيق</h2><p class="muted">طلبات مقدمي الخدمات التي تنتظر مراجعة الإدارة</p></div><div class="stat">${esc(stats.pendingProviders)}</div></div><button class="btn" id="openVerificationQueue" type="button">فتح طلبات التوثيق والموافقة عليها</button></div><div class="grid"><div class="card"><div class="stat">${esc(stats.users)}</div><div>مستخدمون</div></div><div class="card"><div class="stat">${esc(stats.providers)}</div><div>مقدمو خدمات</div></div><div class="card"><div class="stat">${esc(stats.pendingProviders)}</div><div>بانتظار التوثيق</div></div><div class="card"><div class="stat">${esc(stats.activeOrders)}</div><div>طلبات نشطة</div></div><div class="card"><div class="stat">${esc(stats.completedOrders)}</div><div>طلبات مكتملة</div></div><div class="card"><div class="stat">${esc(stats.cancelledOrders)}</div><div>طلبات ملغاة</div></div><div class="card"><div class="stat">${esc(stats.complaints)}</div><div>شكاوى مفتوحة</div></div><div class="card"><div class="stat">${esc(cats.length)}</div><div>أقسام الكتالوج</div></div><div class="card"><div class="stat">${esc(allServices.length)}</div><div>خدمات الكتالوج</div></div></div><h2>طلبات التوثيق</h2><div>${(ps.providers||[]).slice(0,5).map((p:any)=>adminProviderCard(p)).join('')||'<div class="card muted">لا توجد طلبات توثيق معلقة.</div>'}</div>`:''}
      ${activeTab==='providers'?`<div class="card"><div class="row" style="justify-content:space-between"><h2 style="margin:0">مقدمو الخدمات</h2><select id="providerStatusFilter">${providerStatuses.map(x=>`<option value="${x}" ${providerStatus===x?'selected':''}>${esc(x==='PENDING'?'بانتظار التوثيق':x==='VERIFIED'?'موثق':x==='REJECTED'?'مرفوض':'موقوف')}</option>`).join('')}</select></div></div><div>${(ps.providers||[]).map((p:any)=>adminProviderCard(p)).join('')||'<div class="card muted">لا توجد نتائج.</div>'}</div>`:''}
      ${activeTab==='verification'?`<div class="card"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">طلبات توثيق الحسابات</h2><p class="muted">راجع الهوية والترخيص ثم اعتمد الحساب أو ارفضه مع ذكر السبب.</p></div><span class="status">${esc(stats.pendingProviders)} بانتظار المراجعة</span></div></div><div>${(ps.providers||[]).filter((p:any)=>p.verificationStatus==='PENDING').map((p:any)=>adminProviderCard(p)).join('')||'<div class="card muted">لا توجد طلبات توثيق معلقة.</div>'}</div>`:''}
      ${activeTab==='catalog'?`<div class="card"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">كتالوج الخدمات</h2><p class="muted">إدارة الأقسام والخدمات والأسعار والحالة ومخطط بيانات الطلب.</p></div><button class="btn" id="newCategory">+ قسم جديد</button></div></div><div>${cats.map((cat:any)=>`<div class="card"><div class="row" style="justify-content:space-between"><div><b>${esc(cat.icon||'🛠️')} ${esc(cat.name)}</b><div class="muted">${esc(cat.slug)} · ${cat.isActive?'نشط':'معطل'} · ${esc(cat.moduleType||'STANDARD')}</div></div><button class="btn secondary small" data-edit-category="${esc(cat.id)}">تعديل القسم</button></div><div class="row" style="margin-top:10px;flex-wrap:wrap">${(cat.services||[]).map((sv:any)=>`<button class="card" style="text-align:right;min-width:240px;flex:1" data-edit-service="${esc(sv.id)}"><b>${esc(sv.icon||'🛠️')} ${esc(sv.name)}</b><small class="muted">${esc(sv.pricingType==='FIXED'?'سعر ثابت':'عرض سعر')} · ${sv.basePrice===null?'حسب العرض':esc(sv.basePrice+' '+sv.currency)} · ${sv.isActive===false?'معطلة':'نشطة'}</small></button>`).join('')||'<span class="muted">لا توجد خدمات.</span>'}</div></div>`).join('')}</div>`:''}
      ${activeTab==='areas'?`<div class="card"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">المناطق التشغيلية</h2><p class="muted">المناطق مساعدة للمطابقة وليست شرطًا لطلب العميل إذا كانت الإحداثيات صالحة.</p></div><button class="btn" id="newArea">+ منطقة جديدة</button></div></div><div class="card"><div class="admin-table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>النوع</th><th>المركز</th><th>النطاق</th><th>الحالة</th><th></th></tr></thead><tbody>${(areas.areas||[]).map((a:any)=>`<tr><td>${esc(a.name)}</td><td>${esc(a.type)}</td><td>${Number(a.centerLat).toFixed(5)} , ${Number(a.centerLng).toFixed(5)}</td><td>${esc(a.radiusKm)} كم</td><td>${a.isActive?'نشطة':'معطلة'}</td><td><button class="btn secondary small" data-edit-area="${esc(a.id)}">تعديل</button></td></tr>`).join('')||'<tr><td colspan="6" class="muted">لا توجد مناطق.</td></tr>'}</tbody></table></div></div>`:''}
      ${activeTab==='settings'?`<div class="card"><h2>إعدادات المنصة</h2><p class="muted">تُحفظ الإعدادات في قاعدة البيانات. التعديل متاح لـ SUPER_ADMIN فقط.</p></div><div>${(settings.settings||[]).map((x:any)=>`<div class="card"><div class="row" style="justify-content:space-between"><div><b>${esc(x.key)}</b><p class="muted">${esc(x.description)}</p><small>القيمة الحالية: <code>${esc(JSON.stringify(x.value))}</code> · الافتراضي: <code>${esc(JSON.stringify(x.default))}</code></small></div>${state.user!.adminLevel==='SUPER_ADMIN'?`<button class="btn secondary small" data-edit-setting="${esc(x.key)}">تعديل</button>`:''}</div></div>`).join('')}</div>`:''}
      ${activeTab==='account'?`<div class="card"><h2>إعدادات حساب الإدارة</h2><p class="muted">يمكنك تغيير البريد الإلكتروني وكلمة المرور الخاصة بحسابك.</p><button class="btn" id="openAdminAccountSettings" type="button">فتح إعدادات الحساب</button></div>`:''}
      ${activeTab==='orders'?`<div class="card"><div class="row" style="justify-content:space-between"><h2 style="margin:0">الطلبات</h2><select id="orderStatusFilter">${statusOptions.map(x=>`<option value="${x}" ${orderStatus===x?'selected':''}>${esc(x?statusAr(x):'كل الحالات')}</option>`).join('')}</select></div></div><div class="card"><div class="admin-table-wrap"><table class="table"><thead><tr><th>الرقم</th><th>الخدمة</th><th>الحالة</th><th>العميل</th><th>المقدم</th><th>التاريخ</th><th></th></tr></thead><tbody>${(o.orders||[]).map((x:any)=>`<tr><td>${esc(x.code)}</td><td>${esc(x.service?.name||'—')}</td><td>${esc(statusAr(x.status))}</td><td>${esc(x.customer?.fullName||'—')}</td><td>${esc(x.provider?.displayName||'غير مسند')}</td><td>${esc(formatDateTime(x.createdAt))}</td><td><button class="btn secondary small" data-admin-order="${esc(x.id)}">التفاصيل</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">لا توجد طلبات.</td></tr>'}</tbody></table></div></div>`:''}
      ${activeTab==='trips'?`<div class="card"><h2>🛵 إدارة المشاوير</h2><p class="muted">متابعة المشاوير والمسافة والأجرة وحالة مقدم الخدمة.</p></div><div class="card"><div class="admin-table-wrap"><table class="table"><thead><tr><th>المشوار</th><th>الحالة</th><th>العميل</th><th>المقدم</th><th>المسافة</th><th>الأجرة</th></tr></thead><tbody>${(trips.trips||[]).map((x:any)=>`<tr><td>${esc(x.code)}</td><td>${esc(statusAr(x.status))}</td><td>${esc(x.customerName)}</td><td>${esc(x.providerName||'غير مسند')}</td><td>${esc(x.distanceKm)} كم</td><td>${esc(x.fare)} ${esc(x.currency)}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">لا توجد مشاوير.</td></tr>'}</tbody></table></div></div>`:''}
      ${activeTab==='live'?`<div class="card"><h2>📍 المواقع الحية</h2><p class="muted">آخر موقع لمقدمي الخدمات المتصلين. الوصول مقيد بصلاحيات الإدارة.</p></div><div class="grid">${(liveProviders.providers||[]).map((x:any)=>`<div class="card"><b>${esc(x.displayName)}</b><p class="muted">${x.lat!=null?`${Number(x.lat).toFixed(6)} ، ${Number(x.lng).toFixed(6)}`:'لا يوجد موقع حي'}<br>${x.updatedAt?esc(formatDateTime(x.updatedAt)):'—'}</p></div>`).join('')||'<div class="card muted">لا يوجد مقدمو خدمات متصلون.</div>'}</div>`:''}
      ${activeTab==='vehicles'?`<div class="card"><h2>🚗 تحقق المركبات</h2><p class="muted">مراجعة واعتماد مركبات مقدمي الخدمات.</p></div><div>${(vehicles.vehicles||[]).map((x:any)=>`<div class="card"><div class="row" style="justify-content:space-between"><div><b>${esc((x.make||'مركبة')+' '+(x.model||''))}</b><p class="muted">${esc(x.providerName)} · اللوحة: ${esc(x.plate_number||'—')}</p></div><span class="status">${esc(x.status)}</span></div>${x.status==='PENDING'?`<div class="row"><button class="btn" data-verify-vehicle="${esc(x.id)}">اعتماد</button><button class="btn secondary" data-reject-vehicle="${esc(x.id)}">رفض</button></div>`:''}</div>`).join('')||'<div class="card muted">لا توجد مركبات.</div>'}</div>`:''}
      ${activeTab==='safety'?`<div class="card"><h2>🛡️ مراكز الأمان</h2><p class="muted">المراكز التي يمكن للمستخدم الوصول إليها عند الحاجة.</p>${(safety.centers||[]).map((x:any)=>`<div class="card"><b>${esc(x.name)}</b><p class="muted">${esc(x.addressText||'')} · ${esc(x.phone||'')}</p></div>`).join('')||'<p class="muted">لا توجد مراكز مسجلة.</p>'}</div>`:''}
      ${activeTab==='complaints'?`<div>${(c.complaints||[]).map((x:any)=>`<div class="card"><div class="row" style="justify-content:space-between"><div><b>${esc(x.code)}</b><div class="muted">الطلب: ${esc(x.orderId)}</div></div><span class="status">${esc(x.status)}</span></div><p><b>${esc(x.category)}</b> — ${esc(x.description)}</p><div class="row"><button class="btn secondary small" data-admin-complaint="${esc(x.id)}">عرض</button>${!['RESOLVED','REJECTED','CLOSED'].includes(x.status)?`<button class="btn small" data-admin-complaint="${esc(x.id)}">فتح الشكوى والرد</button>`:''}</div></div>`).join('')||'<div class="card muted">لا توجد شكاوى.</div>'}</div>`:''}
      ${activeTab==='admins'&&state.user!.adminLevel==='SUPER_ADMIN'?`<div class="card admin-manager-head"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">المديرون والمشرفون</h2><p class="muted">أنشئ حسابات مستقلة لفريق الإدارة وحدد مستوى الصلاحية لكل حساب.</p></div><button class="btn" id="newAdminAccount" type="button">+ إضافة مشرف</button></div></div><div class="grid admin-users-grid">${(admins.admins||[]).map((x:any)=>`<div class="card admin-user-card"><div class="row" style="justify-content:space-between;align-items:flex-start"><div><b>${esc(x.fullName)}</b><div class="muted">${esc(x.email||'بدون بريد')}</div><small class="muted">${esc(x.phone)}</small></div><span class="status">${esc(x.adminLevel==='SUPER_ADMIN'?'مدير النظام الأعلى':x.adminLevel==='ADMIN'?'مدير':'مشرف')}</span></div><div class="admin-user-meta"><span>${x.status==='ACTIVE'?'🟢 نشط':'🔴 موقوف'}</span><span>آخر دخول: ${x.lastLoginAt?esc(formatDateTime(x.lastLoginAt)):'لم يسجل'}</span></div>${x.adminLevel!=='SUPER_ADMIN'?`<div class="row admin-user-actions"><button class="btn secondary small" data-edit-admin="${esc(x.id)}">تعديل</button><button class="btn secondary small" data-toggle-admin="${esc(x.id)}" data-next-admin-status="${x.status==='ACTIVE'?'SUSPENDED':'ACTIVE'}">${x.status==='ACTIVE'?'إيقاف':'تفعيل'}</button></div>`:''}</div>`).join('')||'<div class="card muted">لا توجد حسابات إضافية.</div>'}</div>`:''}
      ${activeTab==='audit'?`<div class="card"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">سجل العمليات</h2><p class="muted">سجل تدقيق لمراجعة الموافقات والتغييرات والإجراءات الإدارية.</p></div><span class="status">آخر 100 عملية</span></div></div><div class="card"><div class="admin-table-wrap"><table class="table"><thead><tr><th>الوقت</th><th>العملية</th><th>النوع</th><th>المعرّف</th><th>الدور</th></tr></thead><tbody>${(audit.logs||[]).map((x:any)=>`<tr><td>${esc(formatDateTime(x.createdAt))}</td><td>${esc(x.action)}</td><td>${esc(x.entityType||'—')}</td><td>${esc(x.entityId||'—')}</td><td>${esc(x.actorRole||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">لا توجد عمليات مسجلة.</td></tr>'}</tbody></table></div></div>`:''}
      ${activeTab==='users'?`<div class="card"><h2>المستخدمون</h2><table class="table"><thead><tr><th>الاسم</th><th>الهاتف</th><th>الدور</th><th>الحالة</th><th></th></tr></thead><tbody>${(u.users||[]).map((x:any)=>`<tr><td>${esc(x.fullName)}</td><td>${esc(x.phone)}</td><td>${esc(x.role)}</td><td>${esc(x.status)}</td><td>${x.id===state.user!.id?'<span class="muted">حسابك</span>':`<button class="btn secondary small" data-user-status="${esc(x.id)}" data-next-status="${x.status==='ACTIVE'?'SUSPENDED':'ACTIVE'}">${x.status==='ACTIVE'?'تعليق':'تفعيل'}</button>`}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">لا توجد نتائج.</td></tr>'}</tbody></table></div></div>`:''}`);
      document.querySelectorAll('[data-admin-tab]').forEach(x=>x.addEventListener('click',()=>{activeTab=(x as HTMLElement).dataset.adminTab!;history.replaceState(null,'',activeTab==='overview'?'/admin':'/admin?tab='+encodeURIComponent(activeTab));draw()}));
      document.getElementById('openVerificationQueue')?.addEventListener('click',()=>{activeTab='verification';history.replaceState(null,'','/admin?tab=verification');draw()});
      document.getElementById('openAdminAccountSettings')?.addEventListener('click',()=>openAdminAccountEditor());
      document.getElementById('providerStatusFilter')?.addEventListener('change',e=>{providerStatus=(e.target as HTMLSelectElement).value;draw()});
      document.getElementById('orderStatusFilter')?.addEventListener('change',e=>{orderStatus=(e.target as HTMLSelectElement).value;draw()});
      document.querySelectorAll('[data-verify]').forEach(x=>x.addEventListener('click',async()=>{const z=x as HTMLButtonElement;z.disabled=true;try{await api('/admin/providers/'+z.dataset.verify+'/verification',{method:'PATCH',body:JSON.stringify({status:'VERIFIED'})});await draw()}catch(e){z.disabled=false;alert((e as Error).message)}}));
      document.querySelectorAll('[data-reject-provider]').forEach(x=>x.addEventListener('click',async()=>{const z=x as HTMLButtonElement;const reason=prompt('سبب رفض التوثيق (اختياري):','الوثائق غير مكتملة');if(reason===null)return;try{await api('/admin/providers/'+z.dataset.rejectProvider+'/verification',{method:'PATCH',body:JSON.stringify({status:'REJECTED',reason})});await draw()}catch(e){alert((e as Error).message)}}));
      document.querySelectorAll('[data-admin-order]').forEach(x=>x.addEventListener('click',()=>openAdminOrder((x as HTMLElement).dataset.adminOrder!)));
      document.querySelectorAll('[data-admin-file]').forEach(x=>x.addEventListener('click',()=>openPrivateFile((x as HTMLElement).dataset.adminFile!)));
      document.querySelectorAll('[data-admin-complaint]').forEach(x=>x.addEventListener('click',()=>openAdminComplaint((x as HTMLElement).dataset.adminComplaint!)));
      document.querySelectorAll('[data-user-status]').forEach(x=>x.addEventListener('click',async()=>{const z=x as HTMLButtonElement;const reason=prompt(z.dataset.nextStatus==='SUSPENDED'?'سبب تعليق الحساب (اختياري):':'ملاحظة التفعيل (اختيارية):','');if(reason===null)return;try{await api('/admin/users/'+z.dataset.userStatus+'/status',{method:'PATCH',body:JSON.stringify({status:z.dataset.nextStatus,reason})});await draw()}catch(e){alert((e as Error).message)}}));
      document.getElementById('newAdminAccount')?.addEventListener('click',()=>openAdminEditor(null,draw));
      document.querySelectorAll('[data-edit-admin]').forEach(x=>x.addEventListener('click',()=>openAdminEditor((admins.admins||[]).find((z:any)=>z.id===(x as HTMLElement).dataset.editAdmin),draw)));
      document.querySelectorAll('[data-toggle-admin]').forEach(x=>x.addEventListener('click',async()=>{const z=x as HTMLButtonElement;try{await api('/admin/admins/'+z.dataset.toggleAdmin,{method:'PATCH',body:JSON.stringify({status:z.dataset.nextAdminStatus})});await draw()}catch(e){alert((e as Error).message)}}));
      document.getElementById('newCategory')?.addEventListener('click',()=>openCategoryEditor(null,draw));
      document.querySelectorAll('[data-edit-category]').forEach(x=>x.addEventListener('click',()=>openCategoryEditor(cats.find((z:any)=>z.id===(x as HTMLElement).dataset.editCategory),draw)));
      document.querySelectorAll('[data-edit-service]').forEach(x=>x.addEventListener('click',()=>openServiceEditor(allServices.find((z:any)=>z.id===(x as HTMLElement).dataset.editService),cats,draw)));
      document.getElementById('newArea')?.addEventListener('click',()=>openAreaEditor(null,areas.areas||[],draw));
      document.querySelectorAll('[data-edit-area]').forEach(x=>x.addEventListener('click',()=>openAreaEditor((areas.areas||[]).find((z:any)=>z.id===(x as HTMLElement).dataset.editArea),areas.areas||[],draw)));
      document.querySelectorAll('[data-verify-vehicle]').forEach(x=>x.addEventListener('click',async()=>{try{await api('/admin/vehicles/'+(x as HTMLElement).dataset.verifyVehicle,{method:'PATCH',body:JSON.stringify({status:'VERIFIED'})});await draw()}catch(e){alert((e as Error).message)}}));document.querySelectorAll('[data-reject-vehicle]').forEach(x=>x.addEventListener('click',async()=>{const reason=prompt('سبب الرفض:','مستندات المركبة غير مكتملة');if(reason===null)return;try{await api('/admin/vehicles/'+(x as HTMLElement).dataset.rejectVehicle,{method:'PATCH',body:JSON.stringify({status:'REJECTED',reason})});await draw()}catch(e){alert((e as Error).message)}}));document.querySelectorAll('[data-edit-setting]').forEach(x=>x.addEventListener('click',()=>editSetting((x as HTMLElement).dataset.editSetting!,settings.settings||[],draw)));
    }catch(e){shell(`<div class="card error">${esc((e as Error).message)}</div>`)}
  };
  await draw();
}

function openAdminAccountEditor(){
  showModal(`<div class="admin-account-modal"><h2>إعدادات حساب الإدارة</h2><p class="muted">تغيير البريد أو كلمة المرور يتطلب كلمة المرور الحالية. بعد الحفظ تُلغى الجلسات القديمة ويُنشأ تسجيل دخول جديد.</p><form id="adminAccountEditor"><div class="field"><label>الاسم</label><input name="fullName" value="${esc(state.user?.fullName||'')}" minlength="2" maxlength="80"></div><div class="field"><label>البريد الإلكتروني الجديد</label><input name="email" type="email" value="${esc(state.user?.email||'')}" autocomplete="email"></div><div class="field"><label>كلمة المرور الحالية</label><input name="currentPassword" type="password" autocomplete="current-password"></div><div class="field"><label>كلمة المرور الجديدة</label><input name="newPassword" type="password" autocomplete="new-password" minlength="10"><small class="muted">10 أحرف على الأقل وتحتوي على حرف ورقم.</small></div><button class="btn">حفظ التغييرات</button><p id="adminAccountMsg"></p></form></div>`);
  document.getElementById('adminAccountEditor')!.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget as HTMLFormElement;const btn=form.querySelector('button') as HTMLButtonElement;btn.disabled=true;const f=new FormData(form);const body:any={fullName:String(f.get('fullName')||'').trim()};const email=String(f.get('email')||'').trim();const cp=String(f.get('currentPassword')||'');const np=String(f.get('newPassword')||'');if(email)body.email=email;if(cp)body.currentPassword=cp;if(np)body.newPassword=np;try{const j=await api('/admin/account',{method:'PATCH',body:JSON.stringify(body)});saveSession(j);closeModal();await admin()}catch(x){btn.disabled=false;document.getElementById('adminAccountMsg')!.textContent=(x as Error).message;document.getElementById('adminAccountMsg')!.className='error'}});
}
function openAdminEditor(admin:any,refresh:()=>Promise<void>){
  const isEdit=!!admin; showModal(`<div class="admin-account-modal"><h2>${isEdit?'تعديل حساب إداري':'إضافة مشرف أو مدير'}</h2><p class="muted">كل حساب مستقل ويمكن إيقافه دون مشاركة كلمة المرور مع بقية الفريق.</p><form id="adminEditor"><div class="grid"><div class="field"><label>الاسم</label><input name="fullName" value="${esc(admin?.fullName||'')}" required minlength="2" maxlength="80"></div><div class="field"><label>الهاتف</label><input name="phone" value="${esc(admin?.phone||'')}" required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" value="${esc(admin?.email||'')}" required></div><div class="field"><label>${isEdit?'كلمة المرور الجديدة (اختياري)':'كلمة المرور'}</label><input name="password" type="password" ${isEdit?'':'required'} minlength="10"><small class="muted">10 أحرف على الأقل وتحتوي على حرف ورقم.</small></div><div class="field"><label>الصلاحية</label><select name="adminLevel"><option value="SUPPORT" ${admin?.adminLevel==='SUPPORT'?'selected':''}>مشرف</option><option value="ADMIN" ${!admin||admin?.adminLevel==='ADMIN'?'selected':''}>مدير</option></select></div></div><button class="btn">${isEdit?'حفظ التعديلات':'إنشاء الحساب'}</button><p id="adminEditorMsg"></p></form></div>`);
  document.getElementById('adminEditor')!.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget as HTMLFormElement;const btn=form.querySelector('button') as HTMLButtonElement;btn.disabled=true;const f=new FormData(form);const body:any={fullName:String(f.get('fullName')),phone:String(f.get('phone')),email:String(f.get('email')),adminLevel:String(f.get('adminLevel'))};const pw=String(f.get('password')||'');if(pw)body.password=pw;try{await api(isEdit?'/admin/admins/'+admin.id:'/admin/admins',{method:isEdit?'PATCH':'POST',body:JSON.stringify(body)});closeModal();await refresh()}catch(x){btn.disabled=false;document.getElementById('adminEditorMsg')!.textContent=(x as Error).message;document.getElementById('adminEditorMsg')!.className='error'}});
}
function openCategoryEditor(cat:any, refresh:()=>Promise<void>){
  showModal(`<h2>${cat?'تعديل القسم':'إضافة قسم'}</h2><form id="categoryEditor"><div class="grid"><div class="field"><label>الاسم بالعربية</label><input name="ar" value="${esc(cat?.nameI18n?.ar||cat?.name||'')}" required></div><div class="field"><label>الاسم بالإنجليزية</label><input name="en" value="${esc(cat?.nameI18n?.en||'')}"></div><div class="field"><label>Slug</label><input name="slug" value="${esc(cat?.slug||'')}" ${cat?'disabled':''} required></div><div class="field"><label>الأيقونة</label><input name="icon" value="${esc(cat?.icon||'')}"></div><div class="field"><label>ترتيب العرض</label><input name="sortOrder" type="number" value="${esc(cat?.sortOrder??0)}"></div>${cat?`<div class="field"><label>الحالة</label><select name="isActive"><option value="true" ${cat.isActive?'selected':''}>نشط</option><option value="false" ${!cat.isActive?'selected':''}>معطل</option></select></div>`:''}</div><div class="field"><label>الوصف</label><textarea name="description">${esc(cat?.descriptionI18n?.ar||cat?.description||'')}</textarea></div><button class="btn">حفظ</button></form>`);
  document.getElementById('categoryEditor')!.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement);const body:any={name:{ar:String(f.get('ar')),en:String(f.get('en')||'')},description:{ar:String(f.get('description')||'')},icon:String(f.get('icon')||''),sortOrder:Number(f.get('sortOrder')||0)};if(!cat){body.slug=String(f.get('slug'));}else body.isActive=String(f.get('isActive'))==='true';try{await api(cat?'/admin/categories/'+cat.id:'/admin/categories',{method:cat?'PATCH':'POST',body:JSON.stringify(body)});document.querySelector('.modal-backdrop')?.remove();await refresh()}catch(x){alert((x as Error).message)}});
}
function openServiceEditor(sv:any,cats:any[],refresh:()=>Promise<void>){
  const formSchema=sv?.formSchema||[];
  showModal(`<h2>${sv?'تعديل الخدمة':'إضافة خدمة'}</h2><form id="serviceEditor"><div class="grid"><div class="field"><label>القسم</label><select name="categoryId" required>${cats.map((c:any)=>`<option value="${esc(c.id)}" ${sv?.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Slug</label><input name="slug" value="${esc(sv?.slug||'')}" ${sv?'disabled':''} required></div><div class="field"><label>الاسم بالعربية</label><input name="ar" value="${esc(sv?.nameI18n?.ar||sv?.name||'')}" required></div><div class="field"><label>الاسم بالإنجليزية</label><input name="en" value="${esc(sv?.nameI18n?.en||'')}"></div><div class="field"><label>الأيقونة</label><input name="icon" value="${esc(sv?.icon||'')}"></div><div class="field"><label>نوع التسعير</label><select name="pricingType"><option value="FIXED" ${sv?.pricingType==='FIXED'?'selected':''}>سعر ثابت</option><option value="QUOTE" ${sv?.pricingType==='QUOTE'?'selected':''}>عرض سعر</option></select></div><div class="field"><label>السعر الأساسي</label><input name="basePrice" type="number" min="0" step="0.01" value="${esc(sv?.basePrice??'')}"></div><div class="row"><label class="card"><input type="checkbox" name="requiresInspection" ${sv?.requiresInspection?'checked':''}> تحتاج معاينة</label><label class="card"><input type="checkbox" name="requiresVehicle" ${sv?.requiresVehicle?'checked':''}> تحتاج مركبة</label><label class="card"><input type="checkbox" name="supportsWaiting" ${sv?.supportsWaiting?'checked':''}> تدعم الانتظار</label></div><div class="field"><label>الأولوية</label><select name="defaultPriority"><option value="LOW" ${sv?.defaultPriority==='LOW'?'selected':''}>منخفضة</option><option value="NORMAL" ${!sv||sv?.defaultPriority==='NORMAL'?'selected':''}>عادية</option><option value="URGENT" ${sv?.defaultPriority==='URGENT'?'selected':''}>عاجلة</option></select></div>${sv?`<div class="field"><label>الحالة</label><select name="isActive"><option value="true" ${sv.isActive!==false?'selected':''}>نشطة</option><option value="false" ${sv.isActive===false?'selected':''}>معطلة</option></select></div>`:''}</div><div class="field"><label>الوصف</label><textarea name="description">${esc(sv?.descriptionI18n?.ar||sv?.description||'')}</textarea></div><div class="field"><label>مخطط نموذج الطلب JSON</label><textarea name="formSchema" style="min-height:180px;font-family:monospace">${esc(JSON.stringify(formSchema,null,2))}</textarea><small class="muted">يجب أن يكون مصفوفة حقول صحيحة حسب مخطط الخدمة.</small></div><button class="btn">حفظ الخدمة</button></form>`);
  const form=document.getElementById('serviceEditor') as HTMLFormElement;form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form);let fs:any;try{fs=JSON.parse(String(f.get('formSchema')||'[]'));}catch{alert('مخطط JSON غير صالح');return}const body:any={categoryId:String(f.get('categoryId')),name:{ar:String(f.get('ar')),en:String(f.get('en')||'')},description:{ar:String(f.get('description')||'')},icon:String(f.get('icon')||''),pricingType:String(f.get('pricingType')),defaultPriority:String(f.get('defaultPriority')),basePrice:String(f.get('basePrice')||'')===''?undefined:Number(f.get('basePrice')),formSchema:fs,requiresInspection:f.has('requiresInspection'),requiresVehicle:f.has('requiresVehicle'),supportsWaiting:f.has('supportsWaiting')};if(!sv)body.slug=String(f.get('slug'));else body.isActive=String(f.get('isActive'))==='true';try{await api(sv?'/admin/services/'+sv.id:'/admin/services',{method:sv?'PATCH':'POST',body:JSON.stringify(body)});document.querySelector('.modal-backdrop')?.remove();await refresh()}catch(x){alert((x as Error).message)}});
}
function openAreaEditor(area:any,areas:any[],refresh:()=>Promise<void>){
  showModal(`<h2>${area?'تعديل المنطقة':'إضافة منطقة'}</h2><form id="areaEditor"><div class="grid"><div class="field"><label>الاسم بالعربية</label><input name="ar" value="${esc(area?.nameI18n?.ar||area?.name||'')}" required></div><div class="field"><label>الاسم بالإنجليزية</label><input name="en" value="${esc(area?.nameI18n?.en||'')}"></div><div class="field"><label>النوع</label><select name="type" ${area?'disabled':''}><option value="COUNTRY" ${area?.type==='COUNTRY'?'selected':''}>دولة</option><option value="CITY" ${area?.type==='CITY'?'selected':''}>مدينة</option><option value="DISTRICT" ${area?.type==='DISTRICT'?'selected':''}>حي</option></select></div><div class="field"><label>المنطقة الأم</label><select name="parentId"><option value="">بدون</option>${areas.filter((x:any)=>x.id!==area?.id).map((x:any)=>`<option value="${esc(x.id)}" ${area?.parentId===x.id?'selected':''}>${esc(x.name)} (${esc(x.type)})</option>`).join('')}</select></div><div class="field"><label>خط العرض</label><input name="centerLat" type="number" step="0.000001" value="${esc(area?.centerLat??'')}" required></div><div class="field"><label>خط الطول</label><input name="centerLng" type="number" step="0.000001" value="${esc(area?.centerLng??'')}" required></div><div class="field"><label>نصف القطر كم</label><input name="radiusKm" type="number" min="0.1" max="5000" step="0.1" value="${esc(area?.radiusKm??25)}" required></div>${area?`<div class="field"><label>الحالة</label><select name="isActive"><option value="true" ${area.isActive?'selected':''}>نشطة</option><option value="false" ${!area.isActive?'selected':''}>معطلة</option></select></div>`:''}</div><button class="btn">حفظ المنطقة</button></form>`);
  document.getElementById('areaEditor')!.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement);const body:any={name:{ar:String(f.get('ar')),en:String(f.get('en')||'')},centerLat:Number(f.get('centerLat')),centerLng:Number(f.get('centerLng')),radiusKm:Number(f.get('radiusKm'))};if(!area){body.type=String(f.get('type'));body.parentId=String(f.get('parentId')||'')||undefined}else body.isActive=String(f.get('isActive'))==='true';try{await api(area?'/admin/areas/'+area.id:'/admin/areas',{method:area?'PATCH':'POST',body:JSON.stringify(body)});document.querySelector('.modal-backdrop')?.remove();await refresh()}catch(x){alert((x as Error).message)}});
}
async function editSetting(key:string,settings:any[],refresh:()=>Promise<void>){const item=settings.find(x=>x.key===key);if(!item)return;const value=prompt(`القيمة الجديدة للإعداد ${key}\n${item.description}`,JSON.stringify(item.value));if(value===null)return;let parsed:any;try{parsed=JSON.parse(value)}catch{parsed=value}try{await api('/admin/settings/'+encodeURIComponent(key),{method:'PUT',body:JSON.stringify({value:parsed})});await refresh()}catch(e){alert((e as Error).message)}}

function adminProviderCard(p:any){
  const docs=(p.documents||[]).filter((x:any)=>x.docType==='ID'||x.docType==='LICENSE');
  const actions=p.verificationStatus==='PENDING'?`<button class="btn" data-verify="${esc(p.id)}">توثيق الحساب</button><button class="btn secondary" data-reject-provider="${esc(p.id)}">رفض</button>`:'';
  return `<div class="card"><div class="row" style="justify-content:space-between"><div><b>${esc(p.displayName)}</b><div class="muted">${esc(p.fullName)} · ${esc(p.phone)}</div><div class="muted">${esc(p.providerType)} · ${esc(p.email||'بدون بريد')}</div></div><span class="status">${esc(p.verificationStatus)}</span></div><div class="row" style="margin-top:10px">${docs.map((x:any)=>x.fileUrl?`<button class="btn secondary small" type="button" data-admin-file="${esc(x.fileUrl)}">${esc(docTypeAr(x.docType))}</button>`:`<span class="muted">${esc(docTypeAr(x.docType))}: لا يوجد ملف</span>`).join('')||'<span class="muted">لا توجد وثائق هوية/ترخيص.</span>'}</div><div class="row" style="margin-top:10px"><span class="muted">التقييم: ${esc(p.rating??0)} · الطلبات المكتملة: ${esc(p.completedOrders??0)}</span>${actions}</div></div>`;
}
async function openAdminOrder(id:string){
  try{
    const [j,h]=await Promise.all([api('/orders/'+encodeURIComponent(id)),api('/orders/'+encodeURIComponent(id)+'/history')]);
    const o=j.order;
    const loc=o.location||{}; const hasLoc=Number.isFinite(Number(loc.lat))&&Number.isFinite(Number(loc.lng)); const lat=Number(loc.lat),lng=Number(loc.lng);
    const mapUrl=hasLoc?`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lng}#map=18/${lat}/${lng}`:'';
    showModal(`<h2>${esc(o.code)}</h2><div class="grid"><div class="card"><b>الخدمة</b><p>${esc(o.service?.name||'—')}</p></div><div class="card"><b>الحالة</b><p>${esc(statusAr(o.status))}</p></div><div class="card"><b>العميل</b><p>${esc(o.customer?.fullName||'—')}</p></div><div class="card"><b>مقدم الخدمة</b><p>${esc(o.provider?.displayName||'غير مسند')}</p></div></div><div class="card"><b>الوصف</b><p>${esc(o.description)}</p><p class="muted">أُنشئ: ${esc(formatDateTime(o.createdAt))}</p>${hasLoc?`<a class="btn secondary" target="_blank" rel="noopener" href="${mapUrl}">فتح موقع الطلب على الخريطة</a>`:''}</div><h3>سجل حالة الطلب</h3><div class="order-timeline">${(h.history||[]).map((x:any)=>`<div class="timeline-step done"><span class="timeline-dot">✓</span><div><b>${esc(statusAr(x.toStatus))}</b><small>${esc(formatDateTime(x.createdAt))} · ${esc(x.actorRole||'')}</small></div></div>`).join('')}</div>`);
  }catch(e){alert((e as Error).message)}
}
async function openAdminComplaint(id:string){
  try{
    const j=await api('/complaints/'+encodeURIComponent(id));
    const c=j.complaint; const msgs=j.messages||[];
    const closed=['RESOLVED','REJECTED','CLOSED'].includes(c.status);
    const statusMap:any={OPEN:'جديدة',PROVIDER_REPLIED:'بانتظار مراجعة الإدارة',UNDER_REVIEW:'قيد المتابعة',RESOLVED:'تم الحل',REJECTED:'مرفوضة',CLOSED:'مغلقة'};
    const roleMap:any={CUSTOMER:'العميل',PROVIDER:'مقدم الخدمة',ADMIN:'الإدارة'};
    showModal(`<div class="complaint-modal"><h2>⚠️ الشكوى ${esc(c.code)}</h2><p><b>الحالة:</b> <span class="status">${esc(statusMap[c.status]||c.status)}</span> · <b>التصنيف:</b> ${esc(c.category)}</p><div class="card"><b>وصف الشكوى</b><p>${esc(c.description)}</p></div><h3>المحادثة</h3><div class="complaint-thread">${msgs.map((m:any)=>`<div class="card"><div class="row" style="justify-content:space-between"><b>${esc(roleMap[m.authorRole]||m.authorRole)}</b><small class="muted">${esc(formatDateTime(m.createdAt))}</small></div><p>${esc(m.body)}</p></div>`).join('')||'<p class="muted">لا توجد رسائل بعد.</p>'}</div>${!closed?`<form id="adminComplaintReplyForm" class="card" style="margin-top:12px"><h3>الرد على العميل</h3><div class="field"><label>رسالة الرد</label><textarea name="body" minlength="1" maxlength="1000" required placeholder="اكتب رد الإدارة للعميل بوضوح..."></textarea></div><button class="btn" type="submit">إرسال الرد</button></form><div class="card" style="margin-top:12px"><h3>إنهاء الشكوى</h3><p class="muted">بعد مراجعة المحادثة، اختر القرار النهائي. لن تُغلق الشكوى بمجرد الرد فقط.</p><div class="field"><label>القرار</label><select id="adminComplaintAction"><option value="RESTORE_COMPLETED">حل المشكلة وإبقاء الطلب مكتملًا</option><option value="CANCEL_ORDER">إلغاء الطلب</option><option value="WARN_PROVIDER">تنبيه مقدم الخدمة</option><option value="SUSPEND_PROVIDER">إيقاف مقدم الخدمة مؤقتًا</option><option value="DISMISS">رفض الشكوى لعدم ثبوتها</option></select></div><div class="field"><label>ملاحظة القرار</label><textarea id="adminComplaintNote" maxlength="500" placeholder="سبب القرار أو ما تم التحقق منه..."></textarea></div><button class="btn danger" id="closeComplaintBtn" type="button">إغلاق الشكوى وحفظ القرار</button></div>`:`<div class="notice success">تم إنهاء هذه الشكوى. يمكنك مراجعة كامل المراسلات والقرار أعلاه.</div>`}</div>`);
    document.getElementById('adminComplaintReplyForm')?.addEventListener('submit',async e=>{
      e.preventDefault(); const form=e.currentTarget as HTMLFormElement; const btn=form.querySelector('button') as HTMLButtonElement; const body=String(new FormData(form).get('body')||'').trim(); if(!body)return; btn.disabled=true;
      try{await api('/complaints/'+encodeURIComponent(c.id)+'/reply',{method:'POST',body:JSON.stringify({body})});await openAdminComplaint(id)}catch(e){btn.disabled=false;alert((e as Error).message)}
    });
    document.getElementById('closeComplaintBtn')?.addEventListener('click',async()=>{
      const action=String((document.getElementById('adminComplaintAction') as HTMLSelectElement).value); const note=(document.getElementById('adminComplaintNote') as HTMLTextAreaElement).value.trim();
      const btn=document.getElementById('closeComplaintBtn') as HTMLButtonElement; btn.disabled=true;
      try{await api('/admin/complaints/'+encodeURIComponent(id)+'/action',{method:'POST',body:JSON.stringify({action,note})});alert('تم حفظ القرار وإغلاق الشكوى');closeModal();await admin()}catch(e){btn.disabled=false;alert((e as Error).message)}
    });
  }catch(e){alert((e as Error).message)}
}

async function resolveAdminComplaint(id:string,refresh:()=>Promise<void>){ await openAdminComplaint(id); }

const restored=restoreSession();
if(restored){startRealtime().catch(()=>{});startNotificationPolling();flushOrderQueue().catch(()=>{});}
if(page==='provider')provider();else if(page==='admin')admin();else customer();
